// Command gen regenerates everything that is derived from the contract in api/.
//
//	api/events.schema.json  ->  internal/contract/events_schema_gen.go   (the schema, embedded as a constant)
//	api/error-codes.json    ->  internal/contract/error_codes_gen.go     (codes, statuses and UI copy)
//
// The TypeScript side is generated by pnpm scripts from web/package.json, because the generators are node tools.
// CI runs this and fails on a diff, so a schema change that is not regenerated cannot merge (docs/CI.md 1, drift).
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"os"
	"sort"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "gen: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	if err := genEventsSchema("api/events.schema.json", "internal/contract/events_schema_gen.go"); err != nil {
		return err
	}
	return genErrorCodes("api/error-codes.json", "internal/contract/error_codes_gen.go")
}

// genEventsSchema embeds the schema as a raw string. The contract package cannot use go:embed for a file outside
// its own directory, and copying the schema would let two copies drift.
func genEventsSchema(in, out string) error {
	raw, err := os.ReadFile(in)
	if err != nil {
		return err
	}
	var pretty bytes.Buffer
	if err := json.Indent(&pretty, raw, "", "  "); err != nil {
		return fmt.Errorf("%s is not valid JSON: %w", in, err)
	}
	if bytes.Contains(pretty.Bytes(), []byte("`")) {
		return fmt.Errorf("%s contains a backtick, which a raw Go string cannot hold", in)
	}

	var b bytes.Buffer
	b.WriteString("// Code generated by tools/gen from " + in + ". DO NOT EDIT.\n\n")
	b.WriteString("package contract\n\n")
	b.WriteString("// eventsSchema is the session protocol, exactly as api/events.schema.json has it.\n")
	b.WriteString("const eventsSchema = `")
	b.Write(pretty.Bytes())
	b.WriteString("\n`\n")
	return writeGo(out, b.Bytes())
}

type errorRegistry struct {
	Codes []struct {
		Code   string `json:"code"`
		Status int    `json:"status"`
		Copy   string `json:"copy"`
	} `json:"codes"`
	Notices []struct {
		Code  string `json:"code"`
		Level string `json:"level"`
		Copy  string `json:"copy"`
	} `json:"notices"`
}

// genErrorCodes writes the registry as Go, sorted, so the generated file is stable across runs.
func genErrorCodes(in, out string) error {
	raw, err := os.ReadFile(in)
	if err != nil {
		return err
	}
	var reg errorRegistry
	if err := json.Unmarshal(raw, &reg); err != nil {
		return fmt.Errorf("%s: %w", in, err)
	}
	if len(reg.Codes) == 0 {
		return fmt.Errorf("%s has no codes", in)
	}

	sort.Slice(reg.Codes, func(i, j int) bool { return reg.Codes[i].Code < reg.Codes[j].Code })
	sort.Slice(reg.Notices, func(i, j int) bool { return reg.Notices[i].Code < reg.Notices[j].Code })

	var b bytes.Buffer
	b.WriteString("// Code generated by tools/gen from " + in + ". DO NOT EDIT.\n\n")
	b.WriteString("package contract\n\n")
	b.WriteString("// ErrorCode is a stable refusal code. The UI maps it to its own copy.\n")
	b.WriteString("type ErrorCode string\n\n")
	b.WriteString("// Every error code Cairn can answer with.\nconst (\n")
	for _, c := range reg.Codes {
		fmt.Fprintf(&b, "\tCode%s ErrorCode = %q\n", exported(c.Code), c.Code)
	}
	b.WriteString(")\n\n")
	b.WriteString("// errorInfo is the status and the plain-worded copy for each code.\n")
	b.WriteString("var errorInfo = map[ErrorCode]struct {\n\tStatus int\n\tCopy   string\n}{\n")
	for _, c := range reg.Codes {
		fmt.Fprintf(&b, "\tCode%s: {Status: %d, Copy: %q},\n", exported(c.Code), c.Status, c.Copy)
	}
	b.WriteString("}\n\n")
	b.WriteString("// NoticeCode is a stable notice code, for things that are not failures.\n")
	b.WriteString("type NoticeCode string\n\n")
	b.WriteString("// Every notice code Cairn can send.\nconst (\n")
	for _, n := range reg.Notices {
		fmt.Fprintf(&b, "\tNotice%s NoticeCode = %q\n", exported(n.Code), n.Code)
	}
	b.WriteString(")\n\n")
	b.WriteString("// noticeInfo is the level and copy for each notice.\n")
	b.WriteString("var noticeInfo = map[NoticeCode]struct {\n\tLevel string\n\tCopy  string\n}{\n")
	for _, n := range reg.Notices {
		fmt.Fprintf(&b, "\tNotice%s: {Level: %q, Copy: %q},\n", exported(n.Code), n.Level, n.Copy)
	}
	b.WriteString("}\n")
	return writeGo(out, b.Bytes())
}

// writeGo formats generated Go with the standard formatter before writing it, so a generator change cannot leave
// the tree unformatted and turn the lint job red for a cosmetic reason.
func writeGo(out string, src []byte) error {
	formatted, err := format.Source(src)
	if err != nil {
		return fmt.Errorf("%s: generated code does not parse: %w", out, err)
	}
	// Generated source is not a secret; 0644 is what a checked-in file should be.
	return os.WriteFile(out, formatted, 0o644) //nolint:gosec // G306: generated source, not a secret
}

// exported turns a snake_case code into an exported Go identifier.
func exported(code string) string {
	var b bytes.Buffer
	upper := true
	for _, r := range code {
		switch {
		case r == '_':
			upper = true
		case upper:
			if r >= 'a' && r <= 'z' {
				r -= 'a' - 'A'
			}
			b.WriteRune(r)
			upper = false
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}
